contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint d1, uint d2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d1) + (d2)); require(d1 <= 1000000000000000000000000000000); require(d2 <= 1000000000000000000000000000000);
        require(address(this).balance >= d1 + d2, "insufficient test balance");

        c.Deposit{value: d1}(); if (__ESBMC_reverted()) return;
        uint beforeCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        c.Deposit{value: d2}(); if (__ESBMC_reverted()) return;

        uint afterCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        assert(afterCallerBal == beforeCallerBal + d2 && afterContractBal == beforeContractBal + d2);
    }

    receive() external payable {}
}

