pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 d1, uint256 d2) internal {
        d1 = bound(d1, 0, 1000000000000000000000000000000);
        d2 = bound(d2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d1 + d2);
        try c.Deposit{value: d1}() {} catch { return; }
        uint256 beforeCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeCallerBal = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        try c.Deposit{value: d2}() {} catch { return; }
        uint256 afterCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { afterCallerBal = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(afterCallerBal == beforeCallerBal + d2 && afterContractBal == beforeContractBal + d2);
    }

    function testFuzz_run(uint256 d1, uint256 d2) public {
        _run(d1, d2);
    }

    receive() external payable {}
}
